import * as crypto from "node:crypto";
import { capture, serializeHostError } from "./internal/host-error.js";
export const pbkdf2 = (password, salt, iterations, length, digest) => capture(() => new Uint8Array(crypto.pbkdf2Sync(password, salt, iterations, length, digest)), serializeHostError);
export const hkdf = (digest, key, salt, info, length) => capture(() => new Uint8Array(crypto.hkdfSync(digest, key, salt, info, length)), serializeHostError);
export const scrypt = (password, salt, length, cost, blockSize, parallelization, maxmem) => capture(() => new Uint8Array(crypto.scryptSync(password, salt, length, {
    N: cost,
    r: blockSize,
    p: parallelization,
    maxmem: Number(maxmem),
})), serializeHostError);
